/** Legal UI primitives; acknowledgements and persistent records belong to the host. */
export const legalModes={'cookie-consent':['banner','card','inline','compact'],'consent-preferences':['panel','table','cards','compact'],'legal-document':['toc','article','print','compact'],'legal-agreement':['checklist','document','cards','compact'],'consent-history':['table','timeline','cards','compact'],'privacy-request':['form','guided','inline','compact'],'privacy-request-status':['timeline','steps','cards','compact'],'policy-updates':['compare','list','cards','compact']};
