const defaults={searchable:true,filterable:true,dismissible:false,hideOnConsent:false,exportScope:'all',size:'medium',direction:'ltr',bordered:true,disabled:false,readonly:false,status:'ready',placement:'inline',policyVersion:'1',categories:[],sections:[],agreements:[],items:[],updates:[],requestTypes:['access','export','correct','delete','restrict','withdraw'],pageSize:5,maxLength:2000,requireReview:true,requireEmail:true,requireReason:false,allowWithdraw:true,allowCancel:true,allowExport:true,confirmDelete:true,requestTimeout:30000,locale:'zh-CN',timeZone:'Asia/Shanghai',capabilities:['consent','accept','request','cancel','withdraw','acknowledge','export'],labels:{}};
const labels={ready:'就绪',loading:'正在加载',error:'操作失败',empty:'暂无内容',search:'搜索',filter:'筛选',all:'全部',acceptAll:'接受全部',rejectOptional:'仅保留必要项',saveConsent:'保存我的选择',preferences:'自定义偏好',required:'必要',optional:'可选',enabled:'已启用',disabled:'已关闭',alwaysOn:'始终启用',withdraw:'撤回可选同意',acceptAgreement:'确认协议',review:'我已阅读所列文档',agreementRequired:'请阅读并确认所有必选协议',updated:'政策版本已更新，请重新确认',version:'版本',recorded:'已记录',unconfirmed:'尚未确认',purpose:'用途',duration:'保存期限',provider:'提供方',contents:'目录',back:'返回',next:'下一步',previous:'上一页',nextPage:'下一页',pagination:'分页',export:'导出全部记录',details:'查看详情',close:'关闭详情',requestType:'请求类型',email:'联系邮箱',name:'姓名或称呼',reason:'请求说明',submit:'提交请求',access:'查询个人信息',exportData:'获取数据副本',correct:'更正信息',delete:'删除信息',restrict:'限制处理',withdrawType:'撤回同意',pending:'待受理',verifying:'核验中',processing:'处理中',completed:'已完成',rejected:'未受理',cancelled:'已取消',cancelRequest:'取消此请求',refresh:'刷新进度',reference:'请求编号',confirm:'确认',dismiss:'返回修改',confirmText:'请确认此操作；只有服务端确认后才更新记录。',confirmDelete:'我确认发起删除信息请求',acknowledge:'确认已知悉',previousVersion:'上一版本',currentVersion:'当前版本',changed:'变更说明',effective:'生效日期',waiting:'等待服务确认',cancel:'取消本次提交',timeout:'请求超时，请重试',invalid:'配置或数据无效',requiredFields:'请检查必填项及邮箱格式',conflict:'版本冲突，请刷新后重试',success:'服务已确认',noResults:'没有匹配内容',summary:'核对请求',submitted:'提交记录',withdrawn:'已撤回',accepted:'已确认',reasonHint:'请简要说明请求的内容。',closeBanner:'关闭横幅',exportFiltered:'导出筛选结果'};
