function list(v,key,max=2000){if(!Array.isArray(v)||v.length>max)throw TypeError(key);const ids=new Set();for(const x of v){if(!obj(x)||!id(x.id)||ids.has(x.id))throw TypeError(key+' requires unique ids');ids.add(x.id);for(const k of ['title','name','body','description','purpose','duration','provider','before','after','summary','policyVersion','message'])if(x[k]!=null&&(typeof x[k]!=='string'||x[k].length>100000))throw TypeError(k);for(const k of ['required','disabled'])if(x[k]!=null&&typeof x[k]!=='boolean')throw TypeError(k);for(const k of ['time','effectiveAt'])if(x[k]!=null&&(typeof x[k]!=='string'||!Number.isFinite(Date.parse(x[k]))))throw TypeError(k);}return v;}
function recordList(v){list(v,'items');for(const i of v){if(i.choices!=null&&(!obj(i.choices)||Object.entries(i.choices).some(([k,b])=>!id(k)||typeof b!=='boolean')))throw TypeError('record choices');if(i.status!=null&&!['pending','verifying','processing','completed','rejected','cancelled','accepted','withdrawn'].includes(i.status))throw TypeError('status');if(i.steps){list(i.steps,'steps');for(const s of i.steps)if(s.status&&!['pending','verifying','processing','completed','rejected','cancelled'].includes(s.status))throw TypeError('step status');}}return v;}
function validate(o){if(!obj(o)||!Object.hasOwn(legalModes,o.kind)||!legalModes[o.kind].includes(o.mode))throw TypeError('kind/mode');for(const[k,values]of Object.entries({size:['small','medium','large'],direction:['ltr','rtl'],status:['ready','loading','error'],placement:['inline','top','bottom']}))if(!values.includes(o[k]))throw TypeError(k);for(const k of ['searchable','filterable','dismissible','hideOnConsent','bordered','disabled','readonly','requireReview','requireEmail','requireReason','allowWithdraw','allowCancel','allowExport','confirmDelete'])if(typeof o[k]!=='boolean')throw TypeError(k);for(const[k,min,max]of [['pageSize',1,100],['maxLength',1,100000],['requestTimeout',1,300000]])if(!Number.isInteger(o[k])||o[k]<min||o[k]>max)throw TypeError(k);if(!['all','filtered'].includes(o.exportScope))throw TypeError('exportScope');if(!id(o.policyVersion)||!obj(o.labels)||Object.values(o.labels).some(v=>typeof v!=='string'))throw TypeError('version/labels');for(const k of ['categories','sections','agreements','updates'])list(o[k],k);recordList(o.items);if(!Array.isArray(o.requestTypes)||!o.requestTypes.length||o.requestTypes.some(t=>!defaults.requestTypes.includes(t))||new Set(o.requestTypes).size!==o.requestTypes.length)throw TypeError('requestTypes');if(!Array.isArray(o.capabilities)||o.capabilities.some(k=>!defaults.capabilities.includes(k)))throw TypeError('capabilities');new Intl.DateTimeFormat(o.locale,{timeZone:o.timeZone});return o;}
