 function control(label,key,value,type='text',choices,disabled=false){const wrap=make('label',null,'g-legal-field'),n=make(choices?'select':type==='textarea'?'textarea':'input');wrap.append(make('span',label));if(n.tagName==='INPUT')n.type=type;if(['name','email','query'].includes(key))n.maxLength=2000;if(key==='email'){n.autocomplete='email';n.required=options.requireEmail;}if(key==='name')n.autocomplete='name';if(key==='reason')n.required=options.requireReason;n.dataset.legalField=key;n.dataset.legalFocus='field:'+key;n.id=uid+'-'+encodeURIComponent(key);if(choices)for(const c of choices){const option=make('option',c.name||L(c.id));option.value=c.id;n.append(option);}if(type==='checkbox')n.checked=!!value;else n.value=String(value);n.disabled=disabled||locked();if(type==='textarea'){n.rows=4;n.maxLength=options.maxLength;}if(errors[key]){n.setAttribute('aria-invalid','true');n.setAttribute('aria-describedby',n.id+'-error');}wrap.append(n);if(errors[key]){const error=make('small',errors[key],'g-legal-error');error.id=n.id+'-error';wrap.append(error);}return wrap;}
 function time(value){if(!value)return null;const n=make('time',new Intl.DateTimeFormat(options.locale,{timeZone:options.timeZone,year:'numeric',month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'}).format(new Date(value)),'g-legal-muted');n.dateTime=value;return n;}
 function toolbar(filters=['all']){const row=make('div',null,'g-legal-toolbar');if(options.searchable)row.append(control(L('search'),'query',state.query,'search'));if(options.filterable&&filters.length>1)row.append(control(L('filter'),'filter',state.filter,'text',filters.map(id=>({id,name:L(id)}))));return row;}
