 function categories(){const box=make('div',null,'g-legal-categories');if(!options.categories.length)box.append(make('p',L('empty'),'g-legal-empty'));for(const c of options.categories){const row=make('section',null,'g-legal-category');row.append(control((c.name||c.id)+' · '+L(c.required?'required':'optional'),'choice:'+c.id,state.choices[c.id],'checkbox',null,!can('consent')||c.required||c.disabled));if(c.description)row.append(make('p',c.description,'g-legal-muted'));const dl=make('dl',null,'g-legal-metadata');for(const k of ['purpose','provider','duration'])if(c[k])dl.append(make('dt',L(k)),make('dd',c[k]));row.append(dl);if(c.required)row.append(make('small',L('alwaysOn'),'g-legal-muted'));box.append(row);}return box;}
 function consent(){const box=make('div',null,'g-legal-consent'),cookie=options.kind==='cookie-consent';if(cookie)box.append(make('p',options.summary||L('preferences'),'g-legal-text'));if(!cookie||state.preferencesOpen||options.mode==='card')box.append(categories());if(cookie&&options.dismissible)box.append(button(L('closeBanner'),'closeBanner'));if(cookie)box.append(button(L('preferences'),'preferences',undefined,!options.categories.length));const actions=make('div',null,'g-legal-actions');for(const a of ['acceptAll','rejectOptional','saveConsent'])actions.append(button(L(a),a,undefined,!allowed(a)));box.append(actions);if(state.receipt){const r=make('p',L('recorded')+' · '+state.receipt.id+' · '+L('version')+' '+state.receipt.policyVersion,'g-legal-receipt');box.append(r);if(options.allowWithdraw)box.append(button(L('withdraw'),'withdraw',undefined,!allowed('withdraw')));}return box;}
