 function itemCard(i){const n=make('article',null,'g-legal-record');n.dataset.legalItem=i.id;n.append(make('h3',i.title||i.name||i.id),make('span',L(i.status||'pending'),'g-legal-badge'));if(i.policyVersion)n.append(make('p',L('version')+' '+i.policyVersion));const t=time(i.time);if(t)n.append(t);if(i.body||i.summary)n.append(make('p',i.body||i.summary,'g-legal-text'));n.append(button(L('details'),'details',i.id));return n;}
 function history(){const box=make('div');box.append(toolbar(['all','accepted','withdrawn']));const items=match(state.items);if(options.mode==='table'){const table=make('table',null,'g-legal-table'),caption=make('caption',options.title||L('recorded')),head=make('thead'),tr=make('tr');for(const title of [L('reference'),L('version'),L('recorded'),L('details')]){const th=make('th',title);th.scope='col';tr.append(th);}head.append(tr);table.append(caption,head);const body=make('tbody'),page=Math.min(state.page,Math.max(1,Math.ceil(items.length/options.pageSize)));for(const i of items.slice((page-1)*options.pageSize,page*options.pageSize)){const row=make('tr');row.dataset.legalItem=i.id;for(const text of [i.id,i.policyVersion||'—',L(i.status||'accepted')])row.append(make('td',text));const td=make('td');td.append(button(L('details'),'details',i.id));row.append(td);body.append(row);}if(!items.length){const row=make('tr'),td=make('td',L('empty'));td.colSpan=4;row.append(td);body.append(row);}table.append(body);const scroll=make('div',null,'g-legal-scroll');scroll.append(table);box.append(scroll);if(items.length>options.pageSize)box.append(pagination(items.length));}else box.append(paginate(items,itemCard));const active=find(state.active);if(active){const detail=make('section',null,'g-legal-detail');detail.append(button(L('close'),'close'),make('h3',active.id),make('p',active.body||active.summary||L(active.status),'g-legal-text'));if(active.choices){const dl=make('dl',null,'g-legal-metadata');for(const[k,v]of Object.entries(active.choices))dl.append(make('dt',options.categories.find(c=>c.id===k)?.name||k),make('dd',L(v?'enabled':'disabled')));detail.append(dl);}box.append(detail);}if(options.allowExport)box.append(button(L(options.exportScope==='filtered'?'exportFiltered':'export'),'export',undefined,!exportAllowed()||!exportItems().length));return box;}
 const requestLabel=k=>L(k==='export'?'exportData':k==='withdraw'?'withdrawType':k);
 function requestForm(){const box=make('form',null,'g-legal-request');box.noValidate=true;box.setAttribute('aria-label',options.title||L('requestType'));if(options.mode==='guided')box.append(make('p',state.step+' / 2 · '+L(state.step===1?'requestType':'summary'),'g-legal-step'));if(state.step===1||options.mode!=='guided'){box.append(control(L('requestType'),'requestType',state.requestType,'text',options.requestTypes.map(id=>({id,name:requestLabel(id)})),!can('request')),control(L('name'),'name',state.name,'text',null,!can('request')),control(L('email')+(options.requireEmail?' *':''),'email',state.email,'email',null,!can('request')),control(L('reason')+(options.requireReason?' *':''),'reason',state.reason,'textarea',null,!can('request')),make('small',state.reason.length+' / '+options.maxLength+' · '+L('reasonHint'),'g-legal-muted'));}else{const dl=make('dl',null,'g-legal-metadata');for(const[k,v]of [[L('requestType'),requestLabel(state.requestType)],[L('name'),state.name],[L('email'),state.email],[L('reason'),state.reason]])dl.append(make('dt',k),make('dd',v||'—'));box.append(dl);}if(state.requestType==='delete'&&options.confirmDelete)box.append(control(L('confirmDelete'),'deleteConfirmed',state.deleteConfirmed,'checkbox',null,!can('request')));const actions=make('div',null,'g-legal-actions');if(options.mode==='guided'&&state.step===1)actions.append(button(L('next'),'next',undefined,!can('request')));else{if(options.mode==='guided')actions.append(button(L('back'),'back'));actions.append(button(L('submit'),'submit',undefined,!allowed('submit')));}for(const n of actions.querySelectorAll('[data-legal-action=submit],[data-legal-action=next]'))n.type='submit';box.append(actions);if(state.active&&find(state.active))box.append(make('p',L('submitted')+' · '+state.active,'g-legal-receipt'));return box;}
 function requestStatus(){const box=make('div');box.append(toolbar(['all','pending','verifying','processing','completed','rejected','cancelled']));const items=match(state.items);box.append(paginate(items,i=>{const n=itemCard(i);n.querySelector('[data-legal-action=details]')?.remove();const steps=make('ol',null,'g-legal-steps');for(const s of i.steps||[]){const li=make('li');li.append(make('strong',s.title||s.name||s.id),make('span',L(s.status||'pending'),'g-legal-badge'));if(s.body)li.append(make('p',s.body,'g-legal-text'));steps.append(li);}if(i.steps?.length)n.append(steps);n.append(button(L('refresh'),'refresh',i.id,!allowed('refresh',i.id)));if(options.allowCancel)n.append(button(L('cancelRequest'),'cancelRequest',i.id,!allowed('cancelRequest',i.id)));return n;}));return box;}
