 function click(e){const b=e.target.closest?.('[data-legal-action]');if(!own(b)||b.disabled)return;e.preventDefault();const a=b.dataset.legalAction,k=b.dataset.legalKey;if(['cancel','dismiss'].includes(a))return cancel();if(locked())return;if(a==='closeBanner'){if(options.kind==='cookie-consent'&&options.dismissible&&propose({dismissed:true},a))send('dismiss',{reason:'button'});return;}if(a==='page')return propose({page:Number(k)},a);if(a==='details')return propose({active:k},a);if(a==='close')return propose({active:''},a);if(a==='preferences')return propose({preferencesOpen:!state.preferencesOpen},a);if(a==='section'){const n=[...element.querySelectorAll('[data-legal-section]')].find(n=>n.dataset.legalSection===k);n?.scrollIntoView?.({block:'start',behavior:'auto'});n?.focus({preventScroll:true});return;}if(a==='next'){if(can('request')&&validation('submit'))propose({step:2},a);return;}if(a==='back')return propose({step:1},a);if(a==='export')return download();if(['withdraw','cancelRequest'].includes(a)){if(!allowed(a,k))return;confirmation={action:a,key:k};render();element.querySelector('[data-legal-action=confirm]')?.focus();return;}if(a==='confirm'&&confirmation)return request(confirmation.action,confirmation.key);request(a,k);}
